begin;
set local search_path=public,extensions;
select no_plan();
-- Exclusões administrativas preservam o identificador histórico, sem abrir DELETE ao cliente.
insert into public.tenants(id,slug,name) values('40000000-0000-0000-0000-000000000001','historico-review','Histórico');
insert into public.units(id,tenant_id,name) values('40000000-0000-0000-0000-000000000011','40000000-0000-0000-0000-000000000001','Histórico');
select lives_ok($$delete from public.units where id='40000000-0000-0000-0000-000000000011'$$,'DELETE unidade não falha na auditoria');
select lives_ok($$delete from public.tenants where id='40000000-0000-0000-0000-000000000001'$$,'DELETE tenant não falha na auditoria');
select is((select count(*)::int from public.audit_logs where tenant_id='40000000-0000-0000-0000-000000000001' and action='DELETE'),2,'UUIDs históricos preservados após DELETE');
-- Aceite e idempotência só enquanto o acesso continua vigente.
insert into public.tenant_invitations(id,tenant_id,unit_id,email,role,invited_by)
select '40000000-0000-0000-0000-000000000021','10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','b@example.com','manager',id from auth.users where email='a@example.com';
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='b@example.com'),'role','authenticated')::text,true);
set local role authenticated;
select lives_ok($$select public.accept_invitation('40000000-0000-0000-0000-000000000021')$$,'Primeiro aceite válido');
select lives_ok($$select public.accept_invitation('40000000-0000-0000-0000-000000000021')$$,'Reaceite válido idempotente');
reset role;
update public.units set active=false where id='10000000-0000-0000-0000-000000000011';
set local role authenticated;
select throws_ok($$select public.accept_invitation('40000000-0000-0000-0000-000000000021')$$,'42501','Convite indisponível','Reaceite negado: unidade inativa');
reset role;
update public.units set active=true where id='10000000-0000-0000-0000-000000000011';
update public.tenants set status='suspended' where id='10000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select public.accept_invitation('40000000-0000-0000-0000-000000000021')$$,'42501','Convite indisponível','Reaceite negado: tenant suspenso');
reset role;
update public.tenants set status='active' where id='10000000-0000-0000-0000-000000000001';
update public.tenant_entitlements set enabled=false where tenant_id='10000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select public.accept_invitation('40000000-0000-0000-0000-000000000021')$$,'42501','Convite indisponível','Reaceite negado: entitlement desabilitado');
reset role;
update public.tenant_entitlements set enabled=true where tenant_id='10000000-0000-0000-0000-000000000001';
update public.tenant_memberships set status='revoked' where tenant_id='10000000-0000-0000-0000-000000000001' and user_id=(select id from auth.users where email='b@example.com');
set local role authenticated;
select throws_ok($$select public.accept_invitation('40000000-0000-0000-0000-000000000021')$$,'42501','Convite indisponível','Reaceite negado: vínculo revogado');
reset role;
update public.tenant_memberships set status='active' where tenant_id='10000000-0000-0000-0000-000000000001' and user_id=(select id from auth.users where email='b@example.com');
update public.tenant_invitations set revoked_at=now() where id='40000000-0000-0000-0000-000000000021';
set local role authenticated;
select throws_ok($$select public.accept_invitation('40000000-0000-0000-0000-000000000021')$$,'42501','Convite indisponível','Reaceite negado: convite revogado');
reset role;
update public.tenant_invitations set revoked_at=null where id='40000000-0000-0000-0000-000000000021';
-- Admin com todas as suas unidades inativas ou removidas perde também metadados.
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='a@example.com'),'role','authenticated')::text,true);
update public.units set active=false where id='10000000-0000-0000-0000-000000000011';
set local role authenticated;
select is((select count(*)::int from public.tenants),0,'Sem unidade ativa: tenant invisível');
select is((select count(*)::int from public.tenant_entitlements),0,'Sem unidade ativa: entitlement invisível');
select is((select count(*)::int from public.audit_logs),0,'Sem unidade ativa: auditoria invisível');
select ok(not public.check_access('10000000-0000-0000-0000-000000000001',null,'members.manage'),'Sem unidade ativa: não administra tenant');
reset role;
update public.units set active=true where id='10000000-0000-0000-0000-000000000011';
delete from public.membership_units where membership_id=(select id from public.tenant_memberships where user_id=(select id from auth.users where email='a@example.com'));
set local role authenticated;
select is((select count(*)::int from public.tenants),0,'Sem atribuições: tenant invisível');
select ok(not public.check_access('10000000-0000-0000-0000-000000000001',null,'members.manage'),'Sem atribuições: não administra tenant');
reset role;
insert into public.membership_units select tenant_id,id,'10000000-0000-0000-0000-000000000011' from public.tenant_memberships where user_id=(select id from auth.users where email='a@example.com');
-- Snapshot histórico protege os eventos de equipe mesmo após remover atribuições.
update public.membership_units set unit_id='10000000-0000-0000-0000-000000000012' where membership_id=(select id from public.tenant_memberships where tenant_id='10000000-0000-0000-0000-000000000001' and user_id=(select id from auth.users where email='b@example.com'));
update public.tenant_memberships set role='reception' where tenant_id='10000000-0000-0000-0000-000000000001' and user_id=(select id from auth.users where email='b@example.com');
set local role authenticated;
select is((select count(*)::int from public.audit_logs where entity='tenant_memberships' and action='UPDATE' and '10000000-0000-0000-0000-000000000012'=any(scope_unit_ids)),0,'Admin Centro não lê eventos de equipe restrita sem unit_id');
reset role;
delete from public.membership_units where membership_id=(select id from public.tenant_memberships where tenant_id='10000000-0000-0000-0000-000000000001' and user_id=(select id from auth.users where email='b@example.com'));
set local role authenticated;
select is((select count(*)::int from public.audit_logs where entity='tenant_memberships' and action='UPDATE' and '10000000-0000-0000-0000-000000000012'=any(scope_unit_ids)),0,'Remoção de atribuição não libera histórico restrito');
reset role;
update public.tenant_memberships set role='auditor' where user_id=(select id from auth.users where email='a@example.com');
set local role authenticated;
select is((select count(*)::int from public.audit_logs where entity='tenant_memberships' and '10000000-0000-0000-0000-000000000012'=any(scope_unit_ids)),0,'Auditor Centro não lê eventos da unidade restrita');
select ok(exists(select 1 from public.audit_logs where entity='tenant_memberships' and '10000000-0000-0000-0000-000000000011'=any(scope_unit_ids)),'Auditor Centro lê evento no próprio escopo');
reset role;
-- Bootstrap é inicial e usa apenas o trigger normal de auditoria.
insert into private.platform_admin_emails values('review-bootstrap@example.com');
update auth.users set email='review-bootstrap@example.com',email_confirmed_at=now() where email='a@example.com';
select is((select count(*)::int from public.audit_logs where entity='platform_memberships' and entity_id=(select id::text from auth.users where email='review-bootstrap@example.com')),1,'Bootstrap gera um único evento');
update private.platform_memberships set role='implementation',active=false where user_id=(select id from auth.users where email='review-bootstrap@example.com');
update auth.users set email_confirmed_at=now() where email='review-bootstrap@example.com';
select is((select role from private.platform_memberships where user_id=(select id from auth.users where email='review-bootstrap@example.com')),'implementation','Atualização Auth não promove novamente');
select is((select active from private.platform_memberships where user_id=(select id from auth.users where email='review-bootstrap@example.com')),false,'Atualização Auth não reativa papel global');
select throws_ok($$insert into public.tenant_invitations(tenant_id,unit_id,email,role) values('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','a @ b','manager')$$,'23514',null,'Constraint impede e-mail inválido em escrita administrativa');
select * from finish();
rollback;
